import axios from "axios";
import { url } from "./url.service";
import apiClient from "./apiClient";

const serverUrl = url + "/contest";

export const addContest = (formData) => {
  return axios.post(serverUrl + "/addContest", formData);
};

export const addUserContestNote = (formData) => {
  return axios.post(`${serverUrl}/addUserContestNote`, formData);
};

export const getContest = (query) => {
  return apiClient.get(`${serverUrl}/getContestAdmin?${query}`);
};

export const deleteContest = (id) => {
  return axios.delete(`${serverUrl}/deleteById/${id}`);
};

export const updateContest = (formData, id) => {
  return axios.patch(`${serverUrl}/updateById/${id}`, formData);
};
export const getAllJoinedUserContest = (query) => {
  return axios.get(`${serverUrl}/getAllContest`);
};
